package solution

import "testing"

func TestSolution(t *testing.T) {
	if got := SumTo(10); got != 55 {
		t.Errorf("%s = %v", "SumTo(10)", got)
	}
	if got := SumTo(1); got != 1 {
		t.Errorf("%s = %v", "SumTo(1)", got)
	}
	if got := MaxOf([]int{-5, -2, -9}); got != -2 {
		t.Errorf("%s = %v", "MaxOf([]int{-5, -2, -9})", got)
	}
	if got := MaxOf([]int{3, 7, 1}); got != 7 {
		t.Errorf("%s = %v", "MaxOf([]int{3, 7, 1})", got)
	}
	if got := Search([]int{1, 3, 5, 7, 9}, 9); got != 4 {
		t.Errorf("%s = %v", "Search([]int{1, 3, 5, 7, 9}, 9)", got)
	}
	if got := Search([]int{1, 3, 5, 7, 9}, 1); got != 0 {
		t.Errorf("%s = %v", "Search([]int{1, 3, 5, 7, 9}, 1)", got)
	}
	if got := Search([]int{1, 3, 5, 7, 9}, 4); got != -1 {
		t.Errorf("%s = %v", "Search([]int{1, 3, 5, 7, 9}, 4)", got)
	}
	if got := Reverse("abc"); got != "cba" {
		t.Errorf("%s = %v", "Reverse(\"abc\")", got)
	}
	if got := Reverse("a"); got != "a" {
		t.Errorf("%s = %v", "Reverse(\"a\")", got)
	}
	if got := IsPalindrome("Level"); got != true {
		t.Errorf("%s = %v", "IsPalindrome(\"Level\")", got)
	}
	if got := IsPalindrome("abc"); got != false {
		t.Errorf("%s = %v", "IsPalindrome(\"abc\")", got)
	}
	if got := Gcd(12, 18); got != 6 {
		t.Errorf("%s = %v", "Gcd(12, 18)", got)
	}
	if got := Gcd(7, 5); got != 1 {
		t.Errorf("%s = %v", "Gcd(7, 5)", got)
	}
	if got := CountVowels("education"); got != 5 {
		t.Errorf("%s = %v", "CountVowels(\"education\")", got)
	}
	if got := CountVowels("sky"); got != 0 {
		t.Errorf("%s = %v", "CountVowels(\"sky\")", got)
	}
	if got := Fizzbuzz(15); got != "FizzBuzz" {
		t.Errorf("%s = %v", "Fizzbuzz(15)", got)
	}
	if got := Fizzbuzz(9); got != "Fizz" {
		t.Errorf("%s = %v", "Fizzbuzz(9)", got)
	}
	if got := Fizzbuzz(10); got != "Buzz" {
		t.Errorf("%s = %v", "Fizzbuzz(10)", got)
	}
	if got := Fizzbuzz(7); got != "7" {
		t.Errorf("%s = %v", "Fizzbuzz(7)", got)
	}
	if got := Clamp(5, 0, 3); got != 3 {
		t.Errorf("%s = %v", "Clamp(5, 0, 3)", got)
	}
	if got := Clamp(-1, 0, 3); got != 0 {
		t.Errorf("%s = %v", "Clamp(-1, 0, 3)", got)
	}
	if got := Clamp(2, 0, 3); got != 2 {
		t.Errorf("%s = %v", "Clamp(2, 0, 3)", got)
	}
	if got := Average([]int{1, 2}); got != 1.5 {
		t.Errorf("%s = %v", "Average([]int{1, 2})", got)
	}
	if got := Average([]int{2, 4, 6}); got != 4 {
		t.Errorf("%s = %v", "Average([]int{2, 4, 6})", got)
	}
}

