export function sumTo(n: number): number {
  let s = 0;
  for (let i = 1; i < n; i++) {
    s += i;
  }
  return s;
}

export function maxOf(xs: number[]): number {
  let m = xs[0];
  for (const x of xs.slice(1)) {
    if (x > m) m = x;
  }
  return m;
}

export function search(xs: number[], x: number): number {
  let lo = 0;
  let hi = xs.length - 1;
  while (lo <= hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (xs[mid] === x) return mid;
    if (xs[mid] < x) lo = mid + 1;
    else hi = mid - 1;
  }
  return -1;
}

export function reverse(s: string): string {
  let out = "";
  for (let i = s.length - 1; i >= 0; i--) out += s[i];
  return out;
}

export function isPalindrome(s: string): boolean {
  const t = s.toLowerCase();
  return t === [...t].reverse().join("");
}

export function gcd(a: number, b: number): number {
  return b === 0 ? a : gcd(b, a % b);
}

export function countVowels(s: string): number {
  return [...s.toLowerCase()].filter((c) => "aeiou".includes(c)).length;
}

export function fizzbuzz(n: number): string {
  if (n % 15 === 0) return "FizzBuzz";
  if (n % 3 === 0) return "Fizz";
  if (n % 5 === 0) return "Buzz";
  return String(n);
}

export function clamp(x: number, lo: number, hi: number): number {
  if (x < lo) return lo;
  if (x > hi) return hi;
  return x;
}

export function average(xs: number[]): number {
  const s = xs.reduce((a, b) => a + b, 0);
  return s / xs.length;
}

