pub fn sum_to(n: i64) -> i64 {
    let mut s = 0;
    for i in 1..n {
        s += i;
    }
    s
}

pub fn max_of(xs: &[i64]) -> i64 {
    let mut m = xs[0];
    for &x in &xs[1..] {
        if x > m {
            m = x;
        }
    }
    m
}

pub fn search(xs: &[i64], x: i64) -> i64 {
    let (mut lo, mut hi) = (0i64, xs.len() as i64 - 1);
    while lo <= hi {
        let mid = (lo + hi) / 2;
        let v = xs[mid as usize];
        if v == x {
            return mid;
        } else if v < x {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    -1
}

pub fn reverse(s: &str) -> String {
    let c: Vec<char> = s.chars().collect();
    let mut out = String::new();
    let mut i = c.len();
    while i > 0 {
        i -= 1;
        out.push(c[i]);
    }
    out
}

pub fn is_palindrome(s: &str) -> bool {
    let t: Vec<char> = s.to_lowercase().chars().collect();
    t.iter().eq(t.iter().rev())
}

pub fn gcd(a: i64, b: i64) -> i64 {
    if b == 0 {
        a
    } else {
        gcd(b, a % b)
    }
}

pub fn count_vowels(s: &str) -> i64 {
    s.to_lowercase().chars().filter(|c| "aeiou".contains(*c)).count() as i64
}

pub fn fizzbuzz(n: i64) -> String {
    if n % 15 == 0 {
        return "FizzBuzz".to_string();
    }
    if n % 3 == 0 {
        return "Fizz".to_string();
    }
    if n % 5 == 0 {
        return "Buzz".to_string();
    }
    n.to_string()
}

pub fn clamp(x: i64, lo: i64, hi: i64) -> i64 {
    if x < lo {
        return lo;
    }
    if x > hi {
        return hi;
    }
    x
}

pub fn average(xs: &[i64]) -> f64 {
    let s: i64 = xs.iter().sum();
    s as f64 / xs.len() as f64
}

