    assert_eq!(search(&[1, 3, 5, 7, 9], 4), -1);
    assert_eq!(reverse("abc"), "cba");
    assert_eq!(reverse("a"), "a");
    assert_eq!(is_palindrome("Level"), true);
    assert_eq!(is_palindrome("abc"), false);
    assert_eq!(gcd(12, 18), 6);
    assert_eq!(gcd(7, 5), 1);
    assert_eq!(count_vowels("education"), 5);
    assert_eq!(count_vowels("sky"), 0);
    assert_eq!(fizzbuzz(15), "FizzBuzz");
    assert_eq!(fizzbuzz(9), "Fizz");
    assert_eq!(fizzbuzz(10), "Buzz");
    assert_eq!(fizzbuzz(7), "7");
    assert_eq!(clamp(5, 0, 3), 3);
    assert_eq!(clamp(-1, 0, 3), 0);
    assert_eq!(clamp(2, 0, 3), 2);
    assert_eq!(average(&[1, 2]), 1.5);
    assert_eq!(average(&[2, 4, 6]), 4.0);
}

