fn solution() {
    assert_eq!(sum_to(10), 55);
    assert_eq!(sum_to(1), 1);
    assert_eq!(max_of(&[-5, -2, -9]), -2);
    assert_eq!(max_of(&[3, 7, 1]), 7);
